sys_variable_value.value:
(function execute(inputs, outputs) {
// ---- adjust to your instance ----
    var ESCROW        = 'x_2210852_odee_s_0_odee_ticket';

    var PENDING = 'pending', UPDATE_PENDING = 'update_pending', FAILED = 'failed', ABANDONED = 'abandoned';

    var MAX_ATTEMPTS    = 6;
    var BACKOFF_MINUTES = [15, 60, 120, 360, 720];   // last value repeats

    var requeued = 0, abandoned = 0, waiting = 0;
    var now = new GlideDateTime();

    var g = new GlideRecord(ESCROW);
    g.addQuery('u_sync_state', FAILED);
    g.query();

    while (g.next()) {
        var attempts = parseInt(g.u_attempts, 10) || 0;

        // ---- 1. out of budget: give up, loudly ----
        if (attempts >= MAX_ATTEMPTS) {
            g.u_sync_state = ABANDONED;
            g.active       = false;
            g.update();
            abandoned++;
            continue;
        }

        // ---- 2. still inside the backoff window? ----
        if (!isDue(g.u_last_attempt, attempts)) { waiting++; continue; }

        // ---- 3. requeue and let Flow 3's trigger do the work ----
        // u_od_status_id is the reliable "does this exist in OpenData" signal.
        // correlation_id is NOT: it stays empty until the poller backfills it,
        // so using it here would re-POST tickets that already exist.
        var exists = !g.u_od_status_id.nil();
        g.u_sync_state = exists ? UPDATE_PENDING : PENDING;
        g.update();
        requeued++;
    }

    outputs.requeued  = requeued;
    outputs.abandoned = abandoned;
    outputs.waiting   = waiting;

    // ---------------------------------------------------------------

    function isDue(lastAttempt, attempts) {
        if (!lastAttempt || lastAttempt.nil()) return true;   // never stamped: go now

        var idx  = Math.min(Math.max(attempts - 1, 0), BACKOFF_MINUTES.length - 1);
        var due  = new GlideDateTime(lastAttempt.toString());
        due.addSeconds(BACKOFF_MINUTES[idx] * 60);

        return due.compareTo(now) <= 0;
    }
})(inputs, outputs);

